[CmdletBinding()]
param(
    [Parameter(Mandatory)][ValidateScript({ Test-Path $_ })][string]$ComputerList,
    [string]$OutFile = ".\local-admins-$(Get-Date -Format yyyyMMdd).csv"
)
Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'

$computers = Get-Content $ComputerList
$rows = Invoke-Command -ComputerName $computers -ErrorAction Continue -ScriptBlock {
    Get-LocalGroupMember -Group 'Administrators' | ForEach-Object {
        [pscustomobject]@{
            Host   = $env:COMPUTERNAME
            Member = $_.Name
            Type   = $_.ObjectClass
            Source = $_.PrincipalSource
        }
    }
}
$rows | Select-Object Host, Member, Type, Source |
    Export-Csv -Path $OutFile -NoTypeInformation
Write-Host "Wrote $($rows.Count) rows to $OutFile"

$since = (Get-Date).AddMinutes(-10)
$events = Get-WinEvent -FilterHashtable @{
    LogName = 'Security'; Id = 4625; StartTime = $since
}
$events | ForEach-Object {
    $x = [xml]$_.ToXml()
    $d = @{}
    $x.Event.EventData.Data | ForEach-Object { $d[$_.Name] = $_.'#text' }
    [pscustomobject]@{ Account = $d.TargetUserName; Source = $d.IpAddress }
} | Group-Object Account, Source |
    Where-Object Count -ge 20 |
    Sort-Object Count -Descending |
    Select-Object Count, Name

$baseline = Get-Content .\baseline.json | ConvertFrom-Json
$actual = [pscustomobject]@{
    SMB1      = (Get-SmbServerConfiguration).EnableSMB1Protocol
    Firewall  = -not (Get-NetFirewallProfile | Where-Object Enabled -eq 'False')
    Defender  = -not (Get-MpPreference).DisableRealtimeMonitoring
}
foreach ($name in $baseline.PSObject.Properties.Name) {
    if ($actual.$name -ne $baseline.$name) {
        [pscustomobject]@{
            Host = $env:COMPUTERNAME; Setting = $name
            Expected = $baseline.$name; Actual = $actual.$name
        }
    }
}

